/// بسملة المصحف (رسم خطّي بلون النص): تُملأ بعرض السطر وتتّسع بنسبتها.
struct BasmalaView: View {
    private static let parsed = SVGPathParser.path(BasmalaArt.path)

    var body: some View {
        Canvas { ctx, size in
            let s = min(size.width / BasmalaArt.size.width, size.height / BasmalaArt.size.height)
            let w = BasmalaArt.size.width * s, h = BasmalaArt.size.height * s
            var t = CGAffineTransform(translationX: (size.width - w) / 2, y: (size.height - h) / 2)
            t = t.scaledBy(x: s, y: s)
            ctx.fill(Self.parsed.applying(t), with: .color(Sunnah.Colors.textPrimary), style: FillStyle(eoFill: false))
        }
        .accessibilityElement()
        .accessibilityLabel("بسم الله الرحمن الرحيم")
    }
}
